@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupItem {
  + Description : string
  + Category : string
  + RFIDTagged : boolean
}

class VolunteerDriver {
  + DriverID : int
  + AvailableDays : date[]
}

class PickupVehicle {
  + LicensePlateNumber : string
  + StorageSpace : double
}

class DistributionCenter {}

class FoodBank {}

class Client {
  + Name : string
  + Address : string
  + CategoriesNeeded : string[]
}

class DeliveryDriver {}

class PickupRoute {
  + RouteID : int
  + Days : date[]
}

PickupItem "1" -- "*" Resident
VolunteerDriver "1" -- "*" PickupRoute
PickupVehicle "1" -- "*" PickupRoute
DistributionCenter "1" -- "*" PickupVehicle
FoodBank "1" -- "*" PickupVehicle
Client "0..*" DistributionCenter
DeliveryDriver --|> VolunteerDriver

@enduml

